package services

import (
	"context"
	"errors"
	"slices"
	"strconv"
	"strings"
	"time"

	"github.com/argeinfina/hichat/musicworker"
)

// ParseMusicExecutorArgs accepts only the exact argv generated by this server.
// Flags never cross the worker protocol: the worker constructs its own argv.
func ParseMusicExecutorArgs(args []string) (musicworker.Request, error) {
	invalid := &musicworker.Error{Code: "invalid_request"}
	if len(args) < 2 || args[len(args)-2] != "--" {
		return musicworker.Request{}, invalid
	}
	input := args[len(args)-1]
	request := musicworker.Request{Input: input}
	switch {
	case strings.HasPrefix(input, "ytsearch5:"):
		request.Operation = musicworker.OperationSearch
		request.Input = strings.TrimPrefix(input, "ytsearch5:")
		if !slices.Equal(args, searchMusicArgs(request.Input)) {
			return musicworker.Request{}, invalid
		}
	case slices.Equal(args, extractTracksArgs(input)):
		request.Operation = musicworker.OperationMetadata
	default:
		request.Operation = musicworker.OperationAudio
		if index := slices.Index(args, "--download-sections"); index >= 0 {
			if index+1 >= len(args) {
				return musicworker.Request{}, invalid
			}
			section := args[index+1]
			if !strings.HasPrefix(section, "*") || !strings.HasSuffix(section, "-inf") {
				return musicworker.Request{}, invalid
			}
			seconds, err := strconv.ParseInt(strings.TrimSuffix(strings.TrimPrefix(section, "*"), "-inf"), 10, 64)
			if err != nil || seconds <= 0 || seconds > 7*24*60*60 {
				return musicworker.Request{}, invalid
			}
			request.SeekSeconds = seconds
		}
		if !slices.Equal(args, playTrackYtdlpArgs(input, time.Duration(request.SeekSeconds)*time.Second)) {
			return musicworker.Request{}, invalid
		}
	}
	if err := validateMusicWorkerRequest(request); err != nil {
		return musicworker.Request{}, err
	}
	return request, nil
}

func validateMusicWorkerRequest(request musicworker.Request) error {
	invalid := &musicworker.Error{Code: "invalid_request"}
	if len(request.Input) > 4096 || strings.ContainsAny(request.Input, "\x00\r\n") || request.SeekSeconds < 0 || request.SeekSeconds > 7*24*60*60 {
		return invalid
	}
	switch request.Operation {
	case musicworker.OperationSearch:
		if request.SeekSeconds != 0 || strings.TrimSpace(request.Input) != request.Input || request.Input == "" || len([]rune(request.Input)) > 100 {
			return invalid
		}
	case musicworker.OperationMetadata, musicworker.OperationAudio:
		if request.Operation != musicworker.OperationAudio && request.SeekSeconds != 0 {
			return invalid
		}
		if validateMusicURLSyntax(request.Input) != nil {
			return invalid
		}
	default:
		return invalid
	}
	return nil
}

// MusicExecutorErrorLine is deliberately independent of Error() output. Neither
// provider stderr, signed media URLs nor cookie material can reach HF logs.
func MusicExecutorErrorLine(err error) string {
	code := "unknown"
	var typed *musicworker.Error
	if errors.As(err, &typed) {
		switch typed.Code {
		case "forbidden", "bot_check", "unavailable", "age_restricted", "geo_blocked", "rate_limited", "network", "stalled", "tool_missing":
			code = typed.Code
		case "offline":
			code = "network"
		case "busy":
			code = "rate_limited"
		}
	}
	if errors.Is(err, context.DeadlineExceeded) {
		code = "network"
	}
	return "ERROR: HICHAT_MUSIC_ERROR:" + code
}
